      }
      this.loading = false;
    },
    error: (error) => {
      console.error('Error confirming appointment:', error);
      this.errorMessage = 'Failed to confirm appointment. Please try again.';
      this.loading = false;
      setTimeout(() => this.errorMessage = '', 3000);
    }
  });
}

